Index: Record-ML/Sources/MLInfrastructure/MCP/GRDBContextCache.swift
===================================================================
--- Record-ML/Sources/MLInfrastructure/MCP/GRDBContextCache.swift	
+++ Record-ML/Sources/MLInfrastructure/MCP/GRDBContextCache.swift	
@@ -0,0 +1,154 @@
+import Accelerate
+import Domain
+import Foundation
+import GRDB
+import Logging
+@preconcurrency import NaturalLanguage
+
+public actor GRDBContextCache {
+    private let dbPool: DatabasePool
+    private let logger = AppLogger.for(category: "ContextCache")
+    private var nlEmbedding: NLEmbedding?
+
+    public init(databasePath: URL?) throws {
+        if let path = databasePath {
+            try FileManager.default.createDirectory(
+                at: path.deletingLastPathComponent(),
+                withIntermediateDirectories: true
+            )
+            dbPool = try DatabasePool(path: path.path)
+        } else {
+            dbPool = try DatabasePool(path: ":memory:")
+        }
+        try GRDBMigrations.migrator().migrate(dbPool)
+    }
+
+    public func get(query: String, providerID: String, ttlSeconds: Int) throws -> [CachedResult]? {
+        try dbPool.read { db in
+            let rows = try Row.fetchAll(
+                db, sql: GRDBSQL.selectCached,
+                arguments: [query, providerID, ttlSeconds]
+            )
+            guard !rows.isEmpty else { return nil }
+            return rows.map { row in
+                CachedResult(
+                    title: row["title"] ?? "",
+                    body: row["body"] ?? "",
+                    sourceURL: row["source_url"],
+                    providerID: row["provider_id"] ?? "",
+                    relevanceScore: row["relevance_score"] ?? 0
+                )
+            }
+        }
+    }
+
+    public func put(query: String, results: [CachedResult], emptyProviderID: String = "") async throws {
+        let providerIDsToEvict: Set<String> = results.isEmpty
+            ? (emptyProviderID.isEmpty ? [] : [emptyProviderID])
+            : Set(results.map(\.providerID))
+
+        let embeddingBlob: Data? = await embeddingVector(for: query).map { vector in
+            vector.withUnsafeBufferPointer { Data(buffer: $0) }
+        }
+
+        try dbPool.write { db in
+            for pid in providerIDsToEvict {
+                try db.execute(sql: GRDBSQL.deleteCached, arguments: [query, pid])
+            }
+
+            guard !results.isEmpty else {
+                try db.execute(sql: GRDBSQL.insertCached, arguments: [
+                    query, "", "", nil as String?, emptyProviderID, 0.0, embeddingBlob,
+                ])
+                return
+            }
+
+            for result in results {
+                try db.execute(sql: GRDBSQL.insertCached, arguments: [
+                    query, result.title, result.body, result.sourceURL,
+                    result.providerID, result.relevanceScore, embeddingBlob,
+                ])
+            }
+        }
+    }
+
+    public func getSemanticMatch(
+        query: String, providerID: String,
+        ttlSeconds: Int, threshold: Double,
+        matcher: NLEmbedding
+    ) async throws -> [CachedResult]? {
+        let rows: [Row] = try dbPool.read { db in
+            try Row.fetchAll(db, sql: GRDBSQL.selectDistinctQueriesWithEmbeddings, arguments: [providerID])
+        }
+        guard !rows.isEmpty else { return nil }
+
+        guard let queryVector = await embeddingVector(for: query) else {
+            var bestMatch: (query: String, score: Double)?
+            for row in rows {
+                guard let cached: String = row["query_text"] else { continue }
+                let score = matcher.similarity(between: query, and: cached)
+                if score >= threshold, bestMatch.map({ score > $0.score }) ?? true {
+                    bestMatch = (cached, score)
+                }
+            }
+            guard let match = bestMatch else { return nil }
+            return try get(query: match.query, providerID: providerID, ttlSeconds: ttlSeconds)
+        }
+
+        let preFilterThreshold = max(0.0, threshold - 0.3)
+        var candidates: [(query: String, score: Double)] = []
+
+        for row in rows {
+            guard let cached: String = row["query_text"],
+                  let blob = row["embedding"] as? Data else { continue }
+            let storedVector: [Double] = blob.withUnsafeBytes {
+                Array($0.bindMemory(to: Double.self))
+            }
+            let coarse = cosineSimilarity(queryVector, storedVector)
+            if coarse >= preFilterThreshold {
+                candidates.append((cached, coarse))
+            }
+        }
+
+        guard !candidates.isEmpty else { return nil }
+        candidates.sort { $0.score > $1.score }
+        let best = candidates.first!
+        guard best.score >= threshold else { return nil }
+        return try get(query: best.query, providerID: providerID, ttlSeconds: ttlSeconds)
+    }
+
+    public func pruneIfNeeded(maxEntries: Int) throws {
+        try dbPool.write { db in
+            let count = try Int.fetchOne(db, sql: GRDBSQL.countCacheEntries) ?? 0
+            guard count > maxEntries else { return }
+            let excess = count - maxEntries
+            try db.execute(sql: GRDBSQL.pruneCacheOldest, arguments: [excess])
+        }
+    }
+
+    public func entryCount() throws -> Int {
+        try dbPool.read { db in
+            try Int.fetchOne(db, sql: GRDBSQL.countCacheEntries) ?? 0
+        }
+    }
+
+    // MARK: - Embedding helpers
+
+    private func embeddingVector(for text: String) async -> [Double]? {
+        if nlEmbedding == nil {
+            nlEmbedding = await Task.detached(priority: .utility) {
+                NLEmbedding.sentenceEmbedding(for: .english)
+            }.value
+        }
+        return nlEmbedding?.vector(for: text)
+    }
+
+    private func cosineSimilarity(_ a: [Double], _ b: [Double]) -> Double {
+        guard a.count == b.count, !a.isEmpty else { return 0 }
+        let dot = vDSP.dot(a, b)
+        let magA = vDSP.sumOfSquares(a).squareRoot()
+        let magB = vDSP.sumOfSquares(b).squareRoot()
+        guard magA > 0, magB > 0 else { return 0 }
+        return dot / (magA * magB)
+    }
+}

