+import Domain
+import Foundation
+import GRDB
+import Logging
+
+public actor GRDBCommitmentStore: CommitmentStore {
+    private let dbPool: DatabasePool
+    private let logger = AppLogger.for(category: "GRDBCommitments")
+
+    public init(databasePath: URL?) throws {
+        if let path = databasePath {
+            try FileManager.default.createDirectory(
+                at: path.deletingLastPathComponent(),
+                withIntermediateDirectories: true
+            )
+            dbPool = try DatabasePool(path: path.path)
+        } else {
+            dbPool = try DatabasePool(path: ":memory:")
+        }
+        try GRDBMigrations.migrator().migrate(dbPool)
+    }
+
+    // MARK: - CommitmentStore
+
+    public func record(_ commitment: Commitment) async throws {
+        let iso = commitment.createdAt.formatted(Date.ISO8601FormatStyle(includingFractionalSeconds: true))
+        let dueDateStr: String? = commitment.dueDate.map {
+            $0.formatted(.iso8601.year().month().day())
+        }
+        do {
+            try dbPool.write { db in
+                try db.execute(sql: GRDBSQL.insertCommitment, arguments: [
+                    commitment.id.rawValue, commitment.description, commitment.assignee,
+                    dueDateStr, commitment.status.rawValue, commitment.meetingId.rawValue, iso,
+                ])
+            }
+        } catch {
+            throw StorageError.writeFailed(underlying: error)
+        }
+        logger.info("Recorded commitment \(commitment.id, privacy: .private)")
+    }
+
+    public func openCommitments() async throws -> [Commitment] {
+        do {
+            return try dbPool.read { db in
+                let rows = try Row.fetchAll(db, sql: GRDBSQL.selectOpenCommitments)
+                return Self.decodeCommitments(from: rows)
+            }
+        } catch {
+            throw StorageError.readFailed(underlying: error)
+        }
+    }
+
+    public func commitments(for meetingId: RecordingID) async throws -> [Commitment] {
+        do {
+            return try dbPool.read { db in
+                let rows = try Row.fetchAll(db, sql: GRDBSQL.selectCommitmentsForMeeting, arguments: [meetingId.rawValue])
+                return Self.decodeCommitments(from: rows)
+            }
+        } catch {
+            throw StorageError.readFailed(underlying: error)
+        }
+    }
+
+    // MARK: - Private
+
+    private static func decodeCommitments(from rows: [Row]) -> [Commitment] {
+        rows.compactMap { row -> Commitment? in
+            guard let id: String = row["id"],
+                  let desc: String = row["description"],
+                  let statusRaw: String = row["status"],
+                  let mid: String = row["meeting_id"],
+                  let createdStr: String = row["created_at"],
+                  let status = CommitmentStatus(rawValue: statusRaw),
+                  let createdAt = try? Date(
+                      createdStr,
+                      strategy: Date.ISO8601FormatStyle(includingFractionalSeconds: true)
+                  ) else { return nil }
+            let assignee: String? = row["assignee"]
+            let dueDateStr: String? = row["due_date"]
+            let dueDate = dueDateStr.flatMap { try? Date($0, strategy: .iso8601.year().month().day()) }
+            return Commitment(
+                id: CommitmentID(id), description: desc,
+                assignee: assignee, dueDate: dueDate,
+                status: status, meetingId: RecordingID(mid),
+                createdAt: createdAt
+            )
+        }
+    }
+}

