@@ -0,0 +1,56 @@
+import Domain
+import Foundation
+import GRDB
+
+extension GRDBStorageActor: DiarizationReadRepository {
+    public func getSegments(id: RecordingID) async throws -> [DiarizedSegment] {
+        try dbPool.read { db in
+            let rows = try Row.fetchAll(db, sql: GRDBSQL.selectSegments, arguments: [id.rawValue])
+            let decoder = JSONDecoder()
+            return rows.compactMap { row -> DiarizedSegment? in
+                guard let text: String = row["text"],
+                      let sid: String = row["speaker_id"],
+                      let st: Double = row["start_time"],
+                      let et: Double = row["end_time"],
+                      let conf: Double = row["confidence"] else { return nil }
+                let wordTimings: [WordTimestamp]? = (row["word_timings"] as String?).flatMap { json in
+                    json.data(using: .utf8).flatMap { try? decoder.decode([WordTimestamp].self, from: $0) }
+                }
+                return DiarizedSegment(
+                    text: text, speakerId: SpeakerID(rawValue: sid),
+                    startTime: st, endTime: et, confidence: conf,
+                    wordTimings: wordTimings
+                )
+            }
+        }
+    }
+}
+
+extension GRDBStorageActor: DiarizationWriteRepository {
+    public func attachDiarization(id: RecordingID, diarization: DiarizedTranscript) async throws {
+        try guardExists(id: id)
+        await Task.yield()
+        do {
+            try dbPool.write { db in
+                try db.execute(sql: GRDBSQL.updateDiarization, arguments: [
+                    diarization.speakerCount, diarization.processingTime, id.rawValue,
+                ])
+
+                for (idx, seg) in diarization.segments.enumerated() {
+                    try db.execute(sql: GRDBSQL.upsertSegment, arguments: [
+                        id.rawValue, idx, seg.text, seg.speakerId.rawValue,
+                        seg.startTime, seg.endTime, seg.confidence,
+                    ])
+                }
+
+                try db.execute(sql: GRDBSQL.deleteStaleSegments, arguments: [
+                    id.rawValue, diarization.segments.count,
+                ])
+            }
+        } catch let err as StorageError {
+            throw err
+        } catch {
+            throw StorageError.writeFailed(underlying: error)
+        }
+    }
+}

