@@ -0,0 +1,245 @@
+import Domain
+import Foundation
+import GRDB
+import Utilities
+
+extension GRDBStorageActor: RecordingReadRepository {
+    public func getRecording(id: RecordingID) async throws -> StoredRecording {
+        let base: StoredRecording = try dbPool.read { db in
+            guard let row = try Row.fetchOne(db, sql: GRDBSQL.selectRecording, arguments: [id.rawValue]) else {
+                throw StorageError.recordingNotFound(id: id)
+            }
+            return try Self.rowToStoredRecording(row)
+        }
+        guard let baseTranscript = base.transcript else { return base }
+        let diarized = try await getSegments(id: id)
+        let tsSegments: [TranscriptionSegment] = diarized.enumerated().map { idx, seg in
+            TranscriptionSegment(
+                id: .generate(),
+                text: seg.text,
+                startTime: seg.startTime,
+                endTime: seg.endTime,
+                confidence: seg.confidence,
+                isFinal: true,
+                sequenceNumber: idx,
+                wordTimings: seg.wordTimings
+            )
+        }
+        let fullTranscript = TranscriptionResult(
+            segments: tsSegments,
+            fullText: baseTranscript.fullText,
+            processingTime: baseTranscript.processingTime,
+            modelId: baseTranscript.modelId,
+            recordedAt: baseTranscript.recordedAt,
+            computeUnit: baseTranscript.computeUnit,
+            passType: baseTranscript.passType
+        )
+        return StoredRecording(metadata: base.metadata, transcript: fullTranscript)
+    }
+
+    public func listRecordings(limit: Int?, offset: Int?) async throws -> [RecordingSummary] {
+        try dbPool.read { db in
+            let rows = try Row.fetchAll(db, sql: GRDBSQL.listRecordings)
+            return rows.compactMap { row -> RecordingSummary? in
+                guard let id: String = row["id"],
+                      let dateStr: String = row["recorded_at"],
+                      let dur: Double = row["duration"],
+                      let wc: Int = row["word_count"],
+                      let date = Self.parseISO8601(dateStr) else { return nil }
+                return RecordingSummary(
+                    id: RecordingID(id), date: date, duration: dur, wordCount: wc
+                )
+            }
+        }
+    }
+
+    public func totalStorageSize() async throws -> Int64 {
+        try dbPool.read { db in
+            let row = try Row.fetchOne(db, sql: GRDBSQL.totalStorageSize)
+            return row?[0] as? Int64 ?? 0
+        }
+    }
+
+    public func listPendingSessions() async throws -> [RecordingID] {
+        try dbPool.read { db in
+            let rows = try Row.fetchAll(db, sql: GRDBSQL.selectPendingSessions)
+            return rows.compactMap { row -> RecordingID? in
+                guard let id: String = row["id"] else { return nil }
+                return RecordingID(id)
+            }
+        }
+    }
+
+    public func listAllRecordingsWithMetadata() async throws -> [RecordingMetadata] {
+        try dbPool.read { db in
+            let rows = try Row.fetchAll(db, sql: GRDBSQL.listAllRecordingsWithMetadata)
+            return try rows.map { try Self.rowToStoredRecording($0).metadata }
+        }
+    }
+
+    public func listNeedsRetranscription() async throws -> [RecordingID] {
+        try dbPool.read { db in
+            let rows = try Row.fetchAll(db, sql: GRDBSQL.selectNeedsRetranscription)
+            return rows.compactMap { row -> RecordingID? in
+                guard let id: String = row["id"] else { return nil }
+                return RecordingID(id)
+            }
+        }
+    }
+}
+
+extension GRDBStorageActor: RecordingWriteRepository {
+    public func saveRecording(_ file: AudioFile) async throws -> StoredRecording {
+        guard !file.id.rawValue.isEmpty else {
+            throw StorageError.invalidFile(reason: "AudioFile.id must not be empty")
+        }
+        let iso = Self.formatISO8601(file.recordedAt)
+        do {
+            try dbPool.write { db in
+                try db.execute(sql: GRDBSQL.insertRecording, arguments: [
+                    file.id.rawValue, iso, file.duration, Int64(file.fileSize),
+                    file.url.absoluteString, "", 0.0, "none", 0, 0, 0.0, nil as String?,
+                ])
+            }
+        } catch {
+            throw StorageError.writeFailed(underlying: error)
+        }
+        let meta = RecordingMetadata(
+            id: file.id, recordedAt: file.recordedAt, duration: file.duration,
+            fileSize: file.fileSize, audioURL: file.url, transcriptURL: nil,
+            modelId: ModelID(""), processingTime: 0, computeUnit: .unknown, wordCount: 0
+        )
+        return StoredRecording(metadata: meta)
+    }
+
+    public func deleteRecording(id: RecordingID) async throws {
+        let audioURL: URL? = try dbPool.read { db in
+            guard let row = try Row.fetchOne(db, sql: GRDBSQL.selectAudioURL, arguments: [id.rawValue]) else {
+                throw StorageError.recordingNotFound(id: id)
+            }
+            let urlStr: String? = row["audio_url"]
+            return urlStr.flatMap { URL(string: $0) }
+        }
+        if let url = audioURL {
+            let resolvedPath = url.standardizedFileURL.path
+            let allowedRoots = [
+                Directories.recordings.standardizedFileURL.path,
+                FileManager.default.temporaryDirectory.standardizedFileURL.path,
+            ]
+            guard allowedRoots.contains(where: { resolvedPath.hasPrefix($0) }) else {
+                logger.error("deleteRecording: URL outside allowed directories — refusing: \(url.path, privacy: .private)")
+                throw StorageError.invalidFile(reason: "audio URL points outside allowed directories")
+            }
+            do {
+                try FileManager.default.removeItem(at: url)
+            } catch {
+                logger.error("Failed to remove audio file at \(url.path, privacy: .private): \(error, privacy: .private)")
+                throw StorageError.deleteFailed(id: id, underlying: error)
+            }
+        }
+        do {
+            try dbPool.write { db in
+                try db.execute(sql: GRDBSQL.deleteSegments, arguments: [id.rawValue])
+                let changes = try db.execute(sql: GRDBSQL.deleteRecording, arguments: [id.rawValue])
+                guard db.changesCount > 0 else {
+                    throw StorageError.recordingNotFound(id: id)
+                }
+            }
+        } catch let err as StorageError {
+            throw err
+        } catch {
+            throw StorageError.deleteFailed(id: id, underlying: error)
+        }
+    }
+
+    public func markSessionStarted(id: RecordingID, startedAt: Date) async throws {
+        let iso = Self.formatISO8601(startedAt)
+        do {
+            try dbPool.write { db in
+                try db.execute(sql: GRDBSQL.insertPendingSession, arguments: [id.rawValue, iso])
+            }
+        } catch {
+            throw StorageError.writeFailed(underlying: error)
+        }
+    }
+
+    public func updateCleanedMicPath(id: RecordingID, path: URL?) async throws {
+        guard let path else { return }
+        do {
+            try dbPool.write { db in
+                try db.execute(sql: GRDBSQL.updateCleanedMicPath, arguments: [path.absoluteString, id.rawValue])
+            }
+        } catch {
+            throw StorageError.writeFailed(underlying: error)
+        }
+    }
+
+    public func markNeedsRetranscription(id: RecordingID, audioURL: URL) async throws {
+        do {
+            try dbPool.write { db in
+                try db.execute(sql: GRDBSQL.markNeedsRetranscription, arguments: [id.rawValue])
+            }
+        } catch {
+            throw StorageError.writeFailed(underlying: error)
+        }
+        logger.info("Marked recording \(id, privacy: .private) as needs-retranscription; WAV: \(audioURL.lastPathComponent, privacy: .public)")
+    }
+}
+
+// MARK: - Helpers
+
+extension GRDBStorageActor {
+    public func updateAudioDuration(id: RecordingID, duration: Double, fileSize: Int) async throws {
+        do {
+            try dbPool.write { db in
+                try db.execute(sql: GRDBSQL.updateAudioDuration, arguments: [duration, Int64(fileSize), id.rawValue])
+            }
+        } catch {
+            throw StorageError.writeFailed(underlying: error)
+        }
+    }
+
+    static func rowToStoredRecording(_ row: Row) throws -> StoredRecording {
+        guard let id: String = row["id"],
+              let dateStr: String = row["recorded_at"],
+              let dur: Double = row["duration"],
+              let fs: Int64 = row["file_size"],
+              let urlStr: String = row["audio_url"],
+              let mid: String = row["model_id"],
+              let pt: Double = row["processing_time"],
+              let cu: String = row["compute_unit"],
+              let wc: Int = row["word_count"],
+              let date = parseISO8601(dateStr),
+              let audioURL = URL(string: urlStr)
+        else {
+            throw StorageError.readFailed(underlying: nil)
+        }
+        let sc: Int = row["speaker_count"] ?? 0
+        let dt: Double = row["diarization_time"] ?? 0
+        let computeUnit = ComputeUnit(rawValue: cu) ?? .unknown
+        let cleanedMicURL: URL? = (row["cleaned_mic_audio_url"] as String?).flatMap { URL(string: $0) }
+        let meta = RecordingMetadata(
+            id: RecordingID(id), recordedAt: date, duration: dur, fileSize: fs,
+            audioURL: audioURL, transcriptURL: nil, modelId: ModelID(mid),
+            processingTime: pt, computeUnit: computeUnit, wordCount: wc,
+            speakerCount: sc, diarizationTime: dt,
+            cleanedMicAudioPath: cleanedMicURL
+        )
+        let transcriptText: String? = row["transcript_text"]
+        let transcript: TranscriptionResult? = transcriptText.map {
+            TranscriptionResult(
+                segments: [], fullText: $0, processingTime: pt,
+                modelId: ModelID(mid), recordedAt: date, computeUnit: computeUnit, passType: .live
+            )
+        }
+        return StoredRecording(metadata: meta, transcript: transcript)
+    }
+
+    static func parseISO8601(_ string: String) -> Date? {
+        try? Date(string, strategy: Date.ISO8601FormatStyle(includingFractionalSeconds: true))
+    }
+
+    static func formatISO8601(_ date: Date) -> String {
+        date.formatted(Date.ISO8601FormatStyle(includingFractionalSeconds: true))
+    }
+}

