@@ -0,0 +1,45 @@
+import Domain
+import Foundation
+import GRDB
+
+extension GRDBStorageActor: SummaryReadRepository {
+    public func getSummary(for recordingId: RecordingID) async throws -> MeetingSummary? {
+        try dbPool.read { db in
+            guard let row = try Row.fetchOne(db, sql: GRDBSQL.selectSummary, arguments: [recordingId.rawValue]),
+                  let json: String = row["summary_json"],
+                  let data = json.data(using: .utf8) else { return nil }
+            let decoder = JSONDecoder()
+            decoder.dateDecodingStrategy = .iso8601
+            return try decoder.decode(MeetingSummary.self, from: data)
+        }
+    }
+
+    public func recordingIDsWithSummaries() async throws -> Set<RecordingID> {
+        try dbPool.read { db in
+            let rows = try Row.fetchAll(db, sql: GRDBSQL.selectSummaryRecordingIDs)
+            var ids = Set<RecordingID>()
+            for row in rows {
+                if let raw: String = row["recording_id"] {
+                    ids.insert(RecordingID(raw))
+                }
+            }
+            return ids
+        }
+    }
+}
+
+extension GRDBStorageActor: SummaryWriteRepository {
+    public func saveSummary(for recordingId: RecordingID, summary: MeetingSummary) async throws {
+        do {
+            let encoder = JSONEncoder()
