+import Logging
+
+public actor GRDBStorageActor: AdminExecutable {
+    public let dbPool: DatabasePool
+    let logger = AppLogger.for(category: "GRDBStorage")
+
+    public init(databasePath: URL?) throws {
+        if let path = databasePath {
+            try FileManager.default.createDirectory(
+                at: path.deletingLastPathComponent(),
+                withIntermediateDirectories: true
+            )
+            dbPool = try DatabasePool(path: path.path)
+        } else {
+            dbPool = try DatabasePool(path: ":memory:")
+        }
+        try GRDBMigrations.migrator().migrate(dbPool)
+        if let path = databasePath {
+            try FileManager.default.setAttributes(
+                [.posixPermissions: 0o600 as NSNumber],
+                ofItemAtPath: path.path
+            )
+        }
+    }
+
+    public init() throws {
+        let dbDir = Directories.appSupport
+        try Directories.ensureDirectory(at: dbDir)
+        let dbURL = dbDir.appendingPathComponent(
+            AppConstants.Paths.databaseFileName
+                .replacingOccurrences(of: ".duckdb", with: ".sqlite")
+        )
+        try self.init(databasePath: dbURL)
+    }
+
+    // MARK: - AdminExecutable
+
+    public func adminExecute(_ sql: String) async throws {
+        try dbPool.write { db in
+            try db.execute(sql: sql)
+        }
+    }
+
+    // MARK: - Backup
+
+    public func backupDatabase(to destination: URL) async throws {
+        try dbPool.write { db in
+            try db.execute(sql: "PRAGMA wal_checkpoint(TRUNCATE)")
+        }
+        guard let sourcePath = dbPool.path.flatMap({ URL(fileURLWithPath: $0) }) else {
+            throw StorageError.writeFailed(underlying: nil)
+        }
+        let fm = FileManager.default
+        if fm.fileExists(atPath: destination.path) {
+            try fm.removeItem(at: destination)
+        }
+        try fm.copyItem(at: sourcePath, to: destination)
+    }
+
+    public func backupDatabase(source: URL, to destination: URL) async throws {
+        let fm = FileManager.default
+        if fm.fileExists(atPath: destination.path) {
+            try fm.removeItem(at: destination)
+        }
+        try fm.copyItem(at: source, to: destination)
+    }
+}
+
+// MARK: - DatabasePool path helper
