import Accelerate
import SwiftUI

// MARK: - Masthead

/// Newspaper masthead for THE RECORD.
///
/// At rest: static gossamer waveform — looks like a printed editorial mark.
/// Recording: live audio bars animate in real time from WaveformViewModel.magnitudes.
/// The waveform is the recording indicator.
@MainActor
public struct MastheadView: View {
    let waveformVM: WaveformViewModel?
    let isRecording: Bool

    public init(waveformVM: WaveformViewModel? = nil, isRecording: Bool = false) {
        self.waveformVM = waveformVM
        self.isRecording = isRecording
    }

    // MARK: - Static metadata (computed once at launch)

    private static let launchEpoch: Date = {
        var c = Calendar(identifier: .gregorian)
        c.timeZone = TimeZone(secondsFromGMT: 0) ?? .current
        return c.date(from: DateComponents(year: 2026, month: 5, day: 11)) ?? .now
    }()

    // swiftlint:disable no_nsformatter_instantiation
    // safe: SwiftUI View body is @MainActor — this static formatter is only accessed from body
    private static let dateFormatter: DateFormatter = {
        let f = DateFormatter()
        f.dateFormat = "EEEE, d MMMM yyyy"
        return f
    }()

    // swiftlint:enable no_nsformatter_instantiation

    private static let editionNumber: String = {
        let days = Calendar.current.dateComponents([.day], from: launchEpoch, to: .now).day ?? 0
        return String(format: "%03d", max(1, days + 1))
    }()

    @State private var dateline: String = dateFormatter.string(from: .now).uppercased()

    private static let buildId: String =
        (Bundle.main.infoDictionary?["CFBundleVersion"] as? String) ?? "dev"

    // MARK: - Body

    public var body: some View {
        VStack(spacing: 0) {
            Rectangle()
                .fill(Color.ink)
                .frame(height: Metrics.heavyRule)

            ZStack {
                if isRecording {
                    LiveMastheadWave(waveformVM: waveformVM)
                        .transition(.opacity)
                } else {
                    StaticMastheadWave()
                        .transition(.opacity)
                }

                Text("THE RECORD")
                    .font(Typography.masthead)
                    .tracking(14)
                    .foregroundStyle(Color.ink)
            }
            .frame(maxWidth: .infinity, minHeight: 100, idealHeight: 100, maxHeight: 100)
            .animation(.easeInOut(duration: 0.6), value: isRecording)
            .clipped()

            Rectangle()
                .fill(Color.midRule)
                .frame(height: Metrics.hairline)

            HStack {
                Text("Edition \(Self.editionNumber) · \(dateline)")
                    .folio()
                Spacer()
                if isRecording {
                    Text("● REC")
                        .font(Typography.folio)
                        .tracking(1.4)
                        .textCase(.uppercase)
                        .foregroundStyle(Color.breaking)
                        .accessibilityLabel("Recording status")
                        .accessibilityValue("Active")
                } else {
                    Text(Self.buildId)
                        .font(Typography.folio)
                        .tracking(1.4)
                        .foregroundStyle(Color.ink3)
                        .accessibilityLabel("Recording status")
                        .accessibilityValue("Inactive")
                }
            }
            .padding(.horizontal, Metrics.unit * 2)
            .frame(height: 22)
            .animation(.easeInOut(duration: 0.4), value: isRecording)

            Rectangle()
                .fill(Color.ink)
                .frame(height: Metrics.rule)
        }
        .background(Color.bg)
        .task {
            do {
                while !Task.isCancelled {
                    let now = Date.now
                    let midnight = Calendar.current.startOfDay(for: now).addingTimeInterval(86400)
                    try await Task.sleep(for: .seconds(midnight.timeIntervalSince(now)), tolerance: .seconds(60))
                    dateline = Self.dateFormatter.string(from: .now).uppercased()
                }
            } catch {
                // CancellationError — task was cancelled, exit gracefully
            }
        }
    }
}

