                 try db.execute(sql: GRDBSQL.insertCached, arguments: [
                     query, "", "", nil as String?, emptyProviderID, 0.0, embeddingBlob,
                 ])
                 return
             }

             for result in results {
                 try db.execute(sql: GRDBSQL.insertCached, arguments: [
                     query, result.title, result.body, result.sourceURL,
