 import Domain
 import Foundation
 import Logging

 public enum JSONMigrationHelper {
     private static let logger = AppLogger.for(category: "Migration")

     public static func migrate(from jsonBaseDir: URL, reader: some RecordingReadRepository, writer: some RecordingWriteRepository) async throws -> Int {
         let fm = FileManager.default
         guard fm.fileExists(atPath: jsonBaseDir.path) else { return 0 }

         let enumerator = fm.enumerator(
             at: jsonBaseDir,
             includingPropertiesForKeys: [.isRegularFileKey],
             options: [.skipsHiddenFiles]
         )

         var migrated = 0
         let decoder = JSONDecoder()
         while let url = enumerator?.nextObject() as? URL {
             guard url.pathExtension == "json" else { continue }
             do {
                 let data = try await Task.detached(priority: .utility) { try Data(contentsOf: url) }.value
                 let metadata = try decoder.decode(RecordingMetadata.self, from: data)

                 do {
                     _ = try await reader.getRecording(id: metadata.id)
                     continue // already migrated — skip
                 } catch StorageError.recordingNotFound {
                     // not yet in DB — proceed with import
                 }

-                try await writer.importMetadata(metadata)
+                let audioFile = AudioFile(
+                    id: metadata.id,
+                    url: metadata.audioURL,
+                    duration: metadata.duration,
+                    fileSize: metadata.fileSize,
+                    recordedAt: metadata.recordedAt
+                )
+                _ = try await writer.saveRecording(audioFile)
                 migrated += 1
                 logger.info("Migrated \(metadata.id, privacy: .private) from \(url.lastPathComponent, privacy: .public)")
             } catch let decodeError as DecodingError {
                 logger
                     .warning(
                         // swiftlint:disable:next line_length
                         "Skipped \(url.lastPathComponent, privacy: .private) — corrupt JSON: \(decodeError, privacy: .private)"
                     )
             } catch let storageError as StorageError {
                 // DB write failure is more serious than a corrupt source file —
                 // log at .error level so it surfaces in operator dashboards
                 logger
                     .error(
                         // swiftlint:disable:next line_length
                         "Migration write failed for \(url.lastPathComponent, privacy: .private): \(storageError, privacy: .private)"
                     )
             } catch let cocoaError as CocoaError where cocoaError.code == .fileReadNoPermission {
                 logger
                     .error(
                         // swiftlint:disable:next line_length
                         "Permission denied reading \(url.lastPathComponent, privacy: .private): \(cocoaError, privacy: .private)"
                     )
             } catch {
                 logger
                     .warning(
                         // swiftlint:disable:next line_length
                         "Skipped \(url.lastPathComponent, privacy: .private) — \(type(of: error), privacy: .private): \(error, privacy: .private)"
                     )
             }
         }

         logger.info("Migration complete: \(migrated, privacy: .private) recordings imported")
         return migrated
     }
 }

