         let results = try await provider.query(text: "Lambda")

         #expect(results.count >= 1, "ObsidianProvider must return at least one result for matching content")
         let match = try #require(results.first { $0.title.lowercased().contains("lambda") })
         #expect(
             match.body.contains("serverless") || match.body.contains("Lambda"),
             "Result body must contain content from the markdown file"
         )
         #expect(match.providerID == ProviderID("obsidian"))
     }

     // MARK: - AC-E6b: CachingContextProvider serves second query from cache

     @Test(
         "E6b: CachingContextProvider second identical query is a cache hit (inner not called again)",
         .enabled(if: integrationEnabled, "Set RUN_INTEGRATION_TESTS=1 to run this test")
     )
     func cachingContextProviderCacheHit() async throws {
         let vault = try makeTempVault()
         defer { try? FileManager.default.removeItem(at: vault) }

         try "# Kubernetes\nContainer orchestration platform.".write(
             to: vault.appendingPathComponent("k8s.md"),
             atomically: true,
             encoding: .utf8
         )

         let obsidian = ObsidianProvider(vaultPath: vault)

-        // Use in-memory DuckDB cache so the test is hermetic.
-        let cache = try DuckDBContextCache(databasePath: nil)
+        // Use in-memory GRDB cache so the test is hermetic.
+        let cache = try GRDBContextCache(databasePath: nil)
         let cachingProvider = CachingContextProvider(
             inner: obsidian,
             cache: cache,
             ttlSeconds: 3600
         )

         // First query: cache miss — must hit ObsidianProvider.
         let firstResults = try await cachingProvider.query(text: "Kubernetes")
         #expect(firstResults.count >= 1, "First query must return results from ObsidianProvider")

         // Second identical query: cache hit — entry count must not change (no new insert).
         let entriesBeforeSecond = try await cache.entryCount()
         let secondResults = try await cachingProvider.query(text: "Kubernetes")
         let entriesAfterSecond = try await cache.entryCount()

         #expect(
             secondResults.count == firstResults.count,
